<?php $portal=!empty($portal); ?>
<header class="page-header"><div><div class="eyebrow">Billing</div><h1><?= $portal?'My Invoices':'Invoices' ?></h1><p><?= $portal?'View your balances, bank details and payment history.':'Create invoices, track balances and record bank transfers.' ?></p></div><?php if(!$portal): ?><a class="primary-button" href="/invoices/create">+ Create invoice</a><?php endif; ?></header>
<?php if($flash): ?><div class="alert <?= htmlspecialchars($flash['type']) ?>"><?= htmlspecialchars($flash['message']) ?></div><?php endif; ?>
<section class="list-panel"><?php if(!$portal): ?><form class="toolbar invoice-toolbar" method="get" action="/invoices"><div class="search-box"><span>⌕</span><input name="search" value="<?= htmlspecialchars($search) ?>" placeholder="Search invoice or customer..."></div><select name="status" onchange="this.form.submit()"><option value="">All statuses</option><?php foreach(['draft','sent','partially_paid','paid','overdue','void','refunded'] as $value): ?><option value="<?= $value ?>" <?= $status===$value?'selected':'' ?>><?= htmlspecialchars(ucwords(str_replace('_',' ',$value))) ?></option><?php endforeach; ?></select><button class="secondary-button" type="submit">Search</button></form><?php endif; ?>
<?php if($invoices===[]): ?><div class="empty-state tall"><span>▤</span><h3>No invoices found</h3><p><?= $portal?'You do not have any invoices yet.':'Create your first invoice or change the filters.' ?></p><?php if(!$portal): ?><a class="primary-button" href="/invoices/create">Create invoice</a><?php endif; ?></div><?php else: ?><div class="table-wrap"><table class="data-table invoice-table"><thead><tr><th>Invoice</th><th>Customer</th><th>Issued</th><th>Due</th><th>Total</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach($invoices as $item): $customer=$item['company_name']?:$item['contact_name'];$url=($portal?'/portal/invoices/':'/invoices/').(int)$item['id']; ?><tr><td><a class="invoice-reference" href="<?= $url ?>"><strong><?= htmlspecialchars((string)$item['invoice_number']) ?></strong><small><?= htmlspecialchars((string)($item['order_number']?:'Manual invoice')) ?></small></a></td><td><strong><?= htmlspecialchars((string)$customer) ?></strong><small class="table-subline"><?= htmlspecialchars((string)$item['account_number']) ?></small></td><td><?= date('j M Y',strtotime((string)$item['issue_date'])) ?></td><td><?= date('j M Y',strtotime((string)$item['due_date'])) ?></td><td>£<?= number_format($item['total_amount']/100,2) ?></td><td><strong>£<?= number_format($item['balance_due']/100,2) ?></strong></td><td><span class="status <?= htmlspecialchars((string)$item['status']) ?>"><?= htmlspecialchars(ucwords(str_replace('_',' ',(string)$item['status']))) ?></span></td><td><a class="row-action" href="<?= $url ?>">View ›</a></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></section>
